{
  "title": "CSCI-262: Introduction to Computer Science Theory",
  "learningObjectives": [
    "Define formal languages and automata as mathematical models for computation.",
    "Explain how loop invariants and divide-and-conquer strategies structure algorithmic proofs.",
    "Apply asymptotic notation and recurrence relations to analyze resource bounds of recursive algorithms."
  ],
  "beats": [
    {
      "title": "Foundations of Computation",
      "claim": "Computer science theory models computation using formal languages and automata to define what can be computed and how efficiently.",
      "example": "A finite automaton accepts the string 'abab' by transitioning through states that track alternating 'a' and 'b' characters.",
      "visualDirection": "Display a state diagram with labeled transitions for a DFA that accepts alternating 'a' and 'b' strings, highlighting the start and accept states.",
      "sourceIds": ["rit-csci-262", "opendsa"]
    },
    {
      "title": "Formal Languages and Grammars",
      "claim": "Formal languages are sets of strings generated by grammars, which provide a rigorous syntax for describing computational inputs.",
      "example": "A context-free grammar defines valid arithmetic expressions by recursively combining terms and operators.",
      "visualDirection": "Show a parse tree for the expression '3 + 4 * 2' with labeled non-terminals and terminal nodes.",
      "sourceIds": ["rit-csci-262", "opendsa"]
    },
    {
      "title": "Automata Theory Basics",
      "claim": "Automata are mathematical machines that process input strings and accept or reject them based on defined transition rules.",
      "example": "A pushdown automaton recognizes nested parentheses by pushing symbols onto a stack and popping them during matching.",
      "visualDirection": "Illustrate a pushdown automaton with a stack diagram showing push/pop operations during parenthesis matching.",
      "sourceIds": ["rit-csci-262", "opendsa"]
    },
    {

      "title": "Computability Limits",
      "claim": "Computability theory determines which problems can be solved by any algorithm, establishing fundamental boundaries of computation.",
      "example": "The halting problem demonstrates that no general algorithm can decide whether an arbitrary program will eventually stop.",
      "visualDirection": "Present a flowchart showing the decision tree for the halting problem, ending in an undecidable branch.",
      "sourceIds": ["rit-csci-262", "opendsa"]
    },
    {
      "title": "Complexity and Resource Bounds",
      "claim": "Complexity theory classifies algorithms by their time and space requirements, using asymptotic notation to describe growth rates.",
      "example": "A sorting algorithm with O(n log n) time complexity processes larger inputs more efficiently than O(n^2) alternatives.",
      "visualDirection": "Plot two curves on a log-log graph comparing O(n log n) and O(n^2) growth, labeling the axes and intersection point.",
      "sourceIds": ["mit-algorithms", "rit-csci-262"]
    },
    {
      "title": "Loop Invariants and Proofs",
      "claim": "Loop invariants are properties that remain true before and after each iteration, enabling formal verification of algorithm correctness.",
      "example": "In a binary search, the invariant states that the target value, if present, lies within the current search interval.",
      "visualDirection": "Show a table tracking the search interval bounds and the invariant statement across three iterations of binary search.",
      "sourceIds": ["mit-algorithms", "opendsa"]
    },
    {
      "title": "Divide-and-Conquer Strategy",
      "claim": "Divide-and-conquer algorithms break problems into smaller subproblems, solve them recursively, and combine results to form the final solution.",
      "example": "Merge sort splits an array into halves, recursively sorts each half, and merges the sorted halves into a complete sorted array.",
      "visualDirection": "Display a recursive tree diagram showing array splits and merge steps for a 4-element array.",
      "sourceIds": ["mit-algorithms", "rit-csci-262"]
    },
    {
      "title": "Recurrence Relations",
      "claim": "Recurrence relations mathematically describe the cost of recursive algorithms, allowing precise calculation of time complexity.",
      "example": "The recurrence T(n) = 2T(n/2) + O(n) describes the time complexity of merge sort, solving to O(n log n).",
      "visualDirection": "Show a recurrence tree with labeled nodes for T(n) = 2T(n/2) + cn, summing the work at each level.",
      "sourceIds": ["mit-algorithms", "rit-csci-262"]
    },
    {
      "title": "Graph Algorithms and Reachability",
      "claim": "Graph algorithms operate on vertices and edges to solve reachability, ordering, connectivity, and path problems efficiently.",
      "example": "Breadth-first search finds the shortest path in an unweighted graph by exploring neighbors level by level.",
      "visualDirection": "Render a directed graph with BFS traversal order highlighted, showing visited nodes and edge directions.",
      "sourceIds": ["mit-algorithms", "opendsa"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "A disciplined solution states inputs and outputs, proves correctness, and then analyzes time and space to ensure robust algorithmic design.",
      "example": "Before implementing a sorting routine, verify the preconditions, prove the loop invariant, and derive the recurrence for time bounds.",
      "visualDirection": "List a three-step checklist: 1) Define inputs/outputs, 2) Prove correctness via invariants, 3) Analyze complexity with recurrences.",
      "sourceIds": ["mit-algorithms", "rit-csci-262"]
    }
  ]
}
